const sk = sketch('front')
sk.rect(10,20,{at:[20,0]})
const p = spin(sk, 360)
round(p.edge('top','side'), 1)

const sk = sketch('top')
sk.circle(20)
const p = pull(sk, 8)
round(p.edge('top','side'), 1)

const sk = sketch('top')
sk.circle(20)
const p = pull(sk, 8)
bevel(p.edge('bottom','side'), 1)

const sk = sketch('top')
sk.rect(30,20)
const p = pull(sk, 8)
round(p.edge('top','front'), 1)

const sk = sketch('top')
sk.polygon([[0,0],[30,0],[10,20]])
const p = pull(sk, 8)
round(p.edge('top','front'), 1)

const sk = sketch('top')
sk.circle(20)
const p = pull(sk, 8)
round(p.edge('top','front'), 1)
